-- gen599: 70 zone cambiate, 138 tessere
-- fb497bd144f2f21b8182b934bfa80d94 (824233) → 7dc13681561dcd789069adec3fd99854 (833714)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '7dc13681561dcd789069adec3fd99854' as combacia
from kv_store where key like 'tmp:gen599:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen599:p%')
where key='app:jsx:src'
  and md5(value) = 'fb497bd144f2f21b8182b934bfa80d94'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen599:p%') = '7dc13681561dcd789069adec3fd99854';

update kv_store set value = '{"len":833714,"ver":"gen-5.99"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '7dc13681561dcd789069adec3fd99854';

delete from kv_store where key like 'tmp:gen599:p%';
